SELECT CASE WHEN amount >= 3300 THEN 'high' WHEN amount >= 1100 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(CASE WHEN txn_type = 'REFUND' THEN amount ELSE 0 END) AS refund_amount, SUM(CASE WHEN merchant = 'Grab' THEN amount ELSE 0 END) AS grab_amount, ROUND((100 * SUM(CASE WHEN merchant = '7-Eleven' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_7_eleven FROM transactions GROUP BY 1 ORDER BY amount_bucket DESC;
